<!doctype html>
<html lang="en">
<head>
  <meta charset="utf-8">
  <meta name="viewport" content="width=device-width, initial-scale=1">
  <title>Kanban Board</title>
  <style>
    :root {
      --bg: #f4f7fb;
      --surface: #ffffff;
      --text: #1e293b;
      --muted: #64748b;
      --line: #dbe3ee;
      --accent: #2563eb;
      --danger: #dc2626;
      --shadow: 0 8px 24px rgba(30, 41, 59, 0.08);
    }

    * {
      box-sizing: border-box;
    }

    body {
      margin: 0;
      min-height: 100vh;
      color: var(--text);
      background: linear-gradient(135deg, #eef4ff 0%, var(--bg) 45%, #f7f5ff 100%);
      font-family: Arial, Helvetica, sans-serif;
    }

    .app {
      width: min(1200px, calc(100% - 32px));
      margin: 0 auto;
      padding: 40px 0;
    }

    h1 {
      margin: 0 0 24px;
      font-size: clamp(1.75rem, 4vw, 2.5rem);
      letter-spacing: -0.04em;
    }

    .add-bar {
      display: flex;
      gap: 10px;
      margin-bottom: 26px;
    }

    #new-card {
      flex: 1;
      min-width: 0;
      padding: 13px 15px;
      border: 1px solid var(--line);
      border-radius: 10px;
      outline: none;
      font: inherit;
      color: var(--text);
      background: var(--surface);
      box-shadow: 0 2px 8px rgba(30, 41, 59, 0.04);
    }

    #new-card:focus {
      border-color: var(--accent);
      box-shadow: 0 0 0 3px rgba(37, 99, 235, 0.15);
    }

    #add-card {
      padding: 12px 18px;
      border: 0;
      border-radius: 10px;
      cursor: pointer;
      font: inherit;
      font-weight: 700;
      color: white;
      background: var(--accent);
      transition: background 0.15s ease, transform 0.15s ease;
    }

    #add-card:hover {
      background: #1d4ed8;
      transform: translateY(-1px);
    }

    .board {
      display: grid;
      grid-template-columns: repeat(3, minmax(0, 1fr));
      gap: 18px;
      align-items: start;
    }

    .column {
      min-height: 360px;
      border: 1px solid var(--line);
      border-radius: 15px;
      overflow: hidden;
      background: rgba(255, 255, 255, 0.72);
      box-shadow: var(--shadow);
      transition: border-color 0.15s ease, background 0.15s ease;
    }

    .column.drag-over {
      border-color: var(--accent);
      background: #eff6ff;
    }

    .column-header {
      display: flex;
      align-items: center;
      justify-content: space-between;
      padding: 16px 17px;
      border-bottom: 1px solid var(--line);
      background: rgba(255, 255, 255, 0.75);
    }

    .column-header h2 {
      margin: 0;
      font-size: 1rem;
    }

    .count {
      display: inline-grid;
      min-width: 28px;
      height: 28px;
      place-items: center;
      padding: 0 8px;
      border-radius: 999px;
      font-size: 0.8rem;
      font-weight: 700;
      color: #334155;
      background: #e8eef7;
    }

    .card-list {
      min-height: 290px;
      padding: 12px;
    }

    .card {
      display: flex;
      align-items: flex-start;
      justify-content: space-between;
      gap: 12px;
      margin-bottom: 10px;
      padding: 14px;
      border: 1px solid #e3eaf3;
      border-radius: 11px;
      cursor: grab;
      color: var(--text);
      background: var(--surface);
      box-shadow: 0 3px 10px rgba(30, 41, 59, 0.07);
      transition: opacity 0.15s ease, box-shadow 0.15s ease, transform 0.15s ease;
    }

    .card:hover {
      transform: translateY(-1px);
      box-shadow: 0 7px 16px rgba(30, 41, 59, 0.1);
    }

    .card.dragging {
      opacity: 0.45;
    }

    .card-title {
      overflow-wrap: anywhere;
      line-height: 1.4;
    }

    .card-del {
      flex: 0 0 auto;
      width: 27px;
      height: 27px;
      padding: 0;
      border: 0;
      border-radius: 7px;
      cursor: pointer;
      font-size: 1.2rem;
      line-height: 1;
      color: var(--danger);
      background: #fef2f2;
    }

    .card-del:hover {
      color: white;
      background: var(--danger);
    }

    @media (max-width: 760px) {
      .app {
        width: min(100% - 24px, 560px);
        padding-top: 24px;
      }

      .board {
        grid-template-columns: 1fr;
      }

      .column {
        min-height: 180px;
      }

      .card-list {
        min-height: 100px;
      }
    }
  </style>
</head>
<body>
  <main class="app">
    <h1>My Kanban Board</h1>

    <div class="add-bar">
      <input id="new-card" type="text" placeholder="Add a task to To Do…" aria-label="New task">
      <button id="add-card" type="button">Add card</button>
    </div>

    <section class="board" aria-label="Kanban board">
      <section class="column" id="col-todo" data-column="todo">
        <header class="column-header">
          <h2>To Do</h2>
          <span class="count" aria-label="To Do card count">0</span>
        </header>
        <div class="card-list" aria-label="To Do cards"></div>
      </section>

      <section class="column" id="col-doing" data-column="doing">
        <header class="column-header">
          <h2>Doing</h2>
          <span class="count" aria-label="Doing card count">0</span>
        </header>
        <div class="card-list" aria-label="Doing cards"></div>
      </section>

      <section class="column" id="col-done" data-column="done">
        <header class="column-header">
          <h2>Done</h2>
          <span class="count" aria-label="Done card count">0</span>
        </header>
        <div class="card-list" aria-label="Done cards"></div>
      </section>
    </section>
  </main>

  <script>
    (function () {
      "use strict";

      const STORAGE_KEY = "kanban-board-state-v1";
      const input = document.getElementById("new-card");
      const addButton = document.getElementById("add-card");
      const columns = Array.from(document.querySelectorAll(".column"));
      let cards = [];
      let draggedCardId = null;

      function makeId() {
        if (window.crypto && typeof window.crypto.randomUUID === "function") {
          return window.crypto.randomUUID();
        }
        return "card-" + Date.now() + "-" + Math.random().toString(16).slice(2);
      }

      function saveBoard() {
        const orderedCards = [];

        columns.forEach(function (column) {
          const columnName = column.dataset.column;
          column.querySelectorAll(".card").forEach(function (cardElement) {
            const id = cardElement.dataset.cardId;
            const savedCard = cards.find(function (card) {
              return card.id === id;
            });

            if (savedCard) {
              orderedCards.push({
                id: savedCard.id,
                title: savedCard.title,
                column: columnName
              });
            }
          });
        });

        cards = orderedCards;
        localStorage.setItem(STORAGE_KEY, JSON.stringify(cards));
        updateCounts();
      }

      function updateCounts() {
        columns.forEach(function (column) {
          const total = column.querySelectorAll(".card").length;
          const count = column.querySelector(".count");
          count.textContent = total;
          count.setAttribute("aria-label", total + " card" + (total === 1 ? "" : "s"));
        });
      }

      function createCardElement(card) {
        const element = document.createElement("article");
        element.className = "card";
        element.dataset.cardId = card.id;
        element.draggable = true;

        const title = document.createElement("span");
        title.className = "card-title";
        title.textContent = card.title;

        const deleteButton = document.createElement("button");
        deleteButton.className = "card-del";
        deleteButton.type = "button";
        deleteButton.setAttribute("aria-label", "Delete " + card.title);
        deleteButton.textContent = "×";

        deleteButton.addEventListener("click", function () {
          cards = cards.filter(function (item) {
            return item.id !== card.id;
          });
          element.remove();
          saveBoard();
        });

        element.addEventListener("dragstart", function (event) {
          draggedCardId = card.id;
          element.classList.add("dragging");
          event.dataTransfer.effectAllowed = "move";
          event.dataTransfer.setData("text/plain", card.id);
        });

        element.addEventListener("dragend", function () {
          draggedCardId = null;
          element.classList.remove("dragging");
          columns.forEach(function (column) {
            column.classList.remove("drag-over");
          });
        });

        element.append(title, deleteButton);
        return element;
      }

      function addCard(title) {
        const cleanedTitle = title.trim();
        if (!cleanedTitle) return;

        const card = {
          id: makeId(),
          title: cleanedTitle,
          column: "todo"
        };

        cards.push(card);
        document.querySelector("#col-todo .card-list").appendChild(createCardElement(card));
        saveBoard();
      }

      function renderBoard() {
        columns.forEach(function (column) {
          column.querySelector(".card-list").innerHTML = "";
        });

        cards.forEach(function (card) {
          const target = document.querySelector(
            '.column[data-column="' + card.column + '"] .card-list'
          );

          if (target) {
            target.appendChild(createCardElement(card));
          }
        });

        updateCounts();
      }

      function loadBoard() {
        try {
          const saved = JSON.parse(localStorage.getItem(STORAGE_KEY) || "[]");

          if (Array.isArray(saved)) {
            cards = saved.filter(function (card) {
              return card &&
                typeof card.id === "string" &&
                typeof card.title === "string" &&
                ["todo", "doing", "done"].includes(card.column);
            });
          }
        } catch (error) {
          cards = [];
        }

        renderBoard();
      }

      addButton.addEventListener("click", function () {
        addCard(input.value);
        input.value = "";
        input.focus();
      });

      input.addEventListener("keydown", function (event) {
        if (event.key === "Enter") {
          addButton.click();
        }
      });

      columns.forEach(function (column) {
        column.addEventListener("dragover", function (event) {
          event.preventDefault();
          event.dataTransfer.dropEffect = "move";
          column.classList.add("drag-over");
        });

        column.addEventListener("dragleave", function (event) {
          if (!column.contains(event.relatedTarget)) {
            column.classList.remove("drag-over");
          }
        });

        column.addEventListener("drop", function (event) {
          event.preventDefault();
          column.classList.remove("drag-over");

          const cardId = draggedCardId || event.dataTransfer.getData("text/plain");
          const cardElement = Array.from(document.querySelectorAll(".card")).find(function (card) {
            return card.dataset.cardId === cardId;
          });

          if (!cardElement) return;

          column.querySelector(".card-list").appendChild(cardElement);
          saveBoard();
        });
      });

      loadBoard();
    })();
  </script>
</body>
</html>
